import{_ as a,o as s,c as d,a2 as n}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"智算中心投建运 · 赛道总览","description":"智算中心作为重资产的全生命周期拆解——投资、建设、运营","frontmatter":{"title":"智算中心投建运 · 赛道总览","description":"智算中心作为重资产的全生命周期拆解——投资、建设、运营","updated":"2026-08-17T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"智算中心投建运/赛道总览.md","filePath":"智算中心投建运/赛道总览.md","lastUpdated":null}'),e={name:"智算中心投建运/赛道总览.md"};function r(o,t,l,i,p,h){return s(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="智算中心投建运-·-赛道总览" tabindex="-1">智算中心投建运 · 赛道总览 <a class="header-anchor" href="#智算中心投建运-·-赛道总览" aria-label="Permalink to &quot;智算中心投建运 · 赛道总览&quot;">​</a></h1><p><strong>定义：</strong> 智算中心投建运（Invest-Build-Operate）指智算中心作为重资产项目从投资决策、工程建设到运营管理的全生命周期。核心问题：<strong>从&quot;要不要建&quot;到&quot;建在哪、怎么建、建完怎么赚钱&quot;。</strong></p><p><strong>成熟度：</strong> 高速成长期（2026 算电协同写入政府工作报告 + 在建产能集中释放） <strong>PE/VC 重心：</strong> 选址决策、融资结构（REITs/Pre-REITs）、建设交付、算力运营、电力成本管理 <strong>关联专题：</strong> <a href="./../算电协同/赛道总览">算电协同</a>（算力×电力协同关系）| 本专题聚焦资产本身的投建运</p><hr><h2 id="一、为什么现在重要" tabindex="-1">一、为什么现在重要？ <a class="header-anchor" href="#一、为什么现在重要" aria-label="Permalink to &quot;一、为什么现在重要？&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI 算力爆发 → 智算中心成为新一代基础设施</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>    投：千亿资本开支涌入，但项目回报分化极大</span></span>
<span class="line"><span>    建：设备交期（变压器160周）卡住扩张节奏</span></span>
<span class="line"><span>    运：从&quot;包租公&quot;到&quot;算力+能源&quot;运营商转型</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>    核心矛盾：重资产投入 vs 现金流回报周期错配</span></span></code></pre></div><p><strong>关键数据：</strong></p><ul><li>单座千P智算中心总投资约 20-50 亿元（土建+机电+算力设备）</li><li>2025-2030 中国数据中心用电量 CAGR 15-20%（AI 训练+推理驱动）</li><li>2026 年数据中心用电量预计 ~2500-3000 亿 kWh，占全社会用电 ~3%</li><li>电力成本占智算中心运营成本 30-60%</li><li>大型变压器交付周期 2026 年已达 160 周以上（GE Vernova）</li><li>润泽科技 2025 归母净利 50.5 亿（+182%），验证&quot;算力+能源一体化&quot;模式盈利性</li></ul><hr><h2 id="二、投建运三阶段全景" tabindex="-1">二、投建运三阶段全景 <a class="header-anchor" href="#二、投建运三阶段全景" aria-label="Permalink to &quot;二、投建运三阶段全景&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  投（投资决策）        建（工程建设）        运（运营管理）     │</span></span>
<span class="line"><span>│  ─────────────        ─────────────        ─────────────     │</span></span>
<span class="line"><span>│  选址经济学            供配电架构            运营KPI拆解        │</span></span>
<span class="line"><span>│  融资结构              建设周期与供应链       算力定价模式        │</span></span>
<span class="line"><span>│  自建vs租赁vs改造      交付与验收            电力成本管理        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>         ↓                  ↓                  ↓</span></span>
<span class="line"><span>    IRR 8%~18%       工期18→30个月         毛利率 20%~60%</span></span></code></pre></div><h3 id="投-投资决策" tabindex="-1">投（投资决策） <a class="header-anchor" href="#投-投资决策" aria-label="Permalink to &quot;投（投资决策）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心变量</th><th>典型数据</th></tr></thead><tbody><tr><td>选址</td><td>电价、土地、网络、气候、政策</td><td>乌兰察布 vs 长三角电价差显著；绿电直连 84 项目、32.59GW 已审批</td></tr><tr><td>融资</td><td>资本结构、退出路径</td><td>REITs（世纪互联）、Pre-REITs、产业基金、并购</td></tr><tr><td>模式</td><td>自建/租赁/改造</td><td>大厂自建、IDC 厂租建、存量厂房改造三足鼎立</td></tr></tbody></table><h3 id="建-工程建设" tabindex="-1">建（工程建设） <a class="header-anchor" href="#建-工程建设" aria-label="Permalink to &quot;建（工程建设）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心变量</th><th>典型数据</th></tr></thead><tbody><tr><td>供配电</td><td>冗余等级（2N/4N）、电压等级</td><td>800V HVDC 全链路直流；柴发+UPS+电池</td></tr><tr><td>散热</td><td>PUE 硬约束</td><td>新建 DC PUE≤1.15；液冷比风冷节能 30-50%</td></tr><tr><td>交付</td><td>设备交期、建设周期</td><td>变压器 160 周；总工期从 18 个月拉到 30 个月</td></tr></tbody></table><h3 id="运-运营管理" tabindex="-1">运（运营管理） <a class="header-anchor" href="#运-运营管理" aria-label="Permalink to &quot;运（运营管理）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心变量</th><th>典型数据</th></tr></thead><tbody><tr><td>效率</td><td>上架率、PUE、算力利用率</td><td>PUE 降 0.1 + 上架率升 10% → 利润可能翻倍</td></tr><tr><td>定价</td><td>包机柜/按卡时/按 Token</td><td>三种模式的毛利结构和风险差异显著</td></tr><tr><td>能源</td><td>电力成本对冲</td><td>绿电 PPA、储能、需求响应、现货套利四工具箱</td></tr></tbody></table><hr><h2 id="三、与算电协同专题的关系" tabindex="-1">三、与算电协同专题的关系 <a class="header-anchor" href="#三、与算电协同专题的关系" aria-label="Permalink to &quot;三、与算电协同专题的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>算电协同专题</th><th>智算中心投建运专题</th></tr></thead><tbody><tr><td><strong>视角</strong></td><td>能源视角（算力×电力协同）</td><td>资产/经营视角（投建运全周期）</td></tr><tr><td><strong>核心问题</strong></td><td>让电等算力，还是算力等电？</td><td>要不要建、建在哪、怎么建、怎么赚钱？</td></tr><tr><td><strong>已覆盖</strong></td><td>需求响应、绿电直购、PPA、虚拟电厂、液冷、电力市场</td><td>选址、融资、供配电、建设交付、运营 KPI、定价</td></tr><tr><td><strong>交叉点</strong></td><td>—</td><td>#10 电力成本管理（对冲工具箱）</td></tr></tbody></table><blockquote><p>两专题互补：算电协同讲&quot;协同关系&quot;，本专题讲&quot;资产本身&quot;。投建运专题中的电力相关选题（供配电架构、电力成本管理）从<strong>经营成本</strong>角度切入，与算电协同的<strong>市场机制</strong>角度错开。</p></blockquote><hr><h2 id="四、排期与选题地图" tabindex="-1">四、排期与选题地图 <a class="header-anchor" href="#四、排期与选题地图" aria-label="Permalink to &quot;四、排期与选题地图&quot;">​</a></h2><blockquote><p>10 篇系列选题详见 <a href="./选题地图">选题地图</a>，排期已写入选题池（domain: <code>zisuan-toujianyun</code>）。</p></blockquote><table tabindex="0"><thead><tr><th>板块</th><th>篇数</th><th>排期</th></tr></thead><tbody><tr><td>开篇总纲</td><td>1（#1 全景图）</td><td>2026-08-25（周二）</td></tr><tr><td>投（投资决策）</td><td>3（#2-#4）</td><td>2026-08-27 ~ 09-03</td></tr><tr><td>建（工程建设）</td><td>3（#5-#7）</td><td>2026-09-08 ~ 09-15</td></tr><tr><td>运（运营管理）</td><td>3（#8-#10）</td><td>2026-09-17 ~ 09-24</td></tr></tbody></table><hr><p><em>创建：2026-08-17 | 与算电协同专题并列 | 随内容产出持续更新</em></p>`,27)])])}const b=a(e,[["render",r]]);export{u as __pageData,b as default};
